// Platformer starter built from examples/event-sheets (generated by tools/gen_eventsheet_demo.mjs — run that first). Event sheet + behaviors only.
import fs from 'node:fs';
import path from 'node:path';
import { ROOT } from '../lib.mjs';

const ex = path.join(ROOT, 'examples/event-sheets');
const rj = (f) => JSON.parse(fs.readFileSync(path.join(ex, f), 'utf8'));
const walk = (d, base = '') => fs.readdirSync(path.join(d, base), { withFileTypes: true }).flatMap((e) => (e.isDirectory() ? walk(d, path.join(base, e.name)) : [path.join(base, e.name)]));

export default () => {
  const project = rj('nord.project.json');
  const scene = rj('scenes/main.scene.json');
  return {
    name: 'Platformer (event sheet)',
    example: false,
    project: { ...project, name: 'Platformer', id: 'com.crowelian.esplatformer' },
    scenes: { main: { settings: scene.settings, entities: scene.entities } },
    prefabs: { 'prefabs/bullet.prefab.json': rj('prefabs/bullet.prefab.json').root },
    files: { 'events/main.events.json': rj('events/main.events.json') },
    assets: walk(ex, 'assets').filter((f) => !f.endsWith('.meta.json')).map((f) => f.split(path.sep).join('/')).map((f) => ({ from: path.posix.join('examples/event-sheets', f), to: f })),
    template: { id: 'es-platformer', title: 'Platformer (event sheet)', description: 'Platform behavior, coins, slimes, a turret and a goal — everything is an event sheet. The tutorial T24 game.' },
    readme: '# Platformer (event sheet)\nA/D or arrows run, Space jumps (twice). Collect coins, avoid slimes and the turret, reach the flag. Drag the star with the mouse. No scripts: read `events/main.events.json` in the **Event sheets** tab.\n',
  };
};
